import { Table, DecimalColumn, GenericColumn, StringColumn } from '../../db'

export const sys_app_category = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        update_synch: true,
    },
    extends: 'sys_metadata',
    label: 'Menu Category',
    name: 'sys_app_category',
    schema: {
        default_order: DecimalColumn({
            label: 'Default order',
            maxLength: 15,
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        style: StringColumn({
            label: [
                {
                    hint: 'CSS style for the application menu',
                    label: 'Style',
                    plural: 'Styles',
                },
            ],
            maxLength: 100,
        }),
        name: StringColumn({
            label: 'Name',
            unique: true,
        }),
    },
    textIndex: true,
})
